sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float angle;
uniform float mask;
uniform float style;
half4 main(float2 coord) {
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a));
    float2 v = coord - size * 0.5;
    float along = dot(v, d);
    float2 q = coord + d * (along / max(scale, 0.01) - along);
    if (style > 0.5) {
        if (scale <= 0.0 || coord.x < 0.0 || coord.y < 0.0 || coord.x > size.x || coord.y > size.y) return half4(0.0);
        q = clamp(q, float2(0.5), size - 0.5);
    }
    half4 color = image.eval(q);
    if (mask > 0.5) color *= image.eval(coord).a;
    return color;
}
